package com.example.approval.adapter;
import com.example.approval.application.*;import com.example.approval.domain.*;import org.junit.jupiter.api.Test;import java.time.Instant;import static org.assertj.core.api.Assertions.*;
class InMemoryAdaptersTest {@Test void fixedClockAndRepositorySnapshotsAreDeterministic(){var time=Instant.parse("2026-01-01T00:00:00Z");var clock=new FixedClockAdapter(time);assertThat(clock.now()).isEqualTo(time);var repo=new InMemoryExpenseRequestRepository();var r=ExpenseRequest.draft(ExpenseRequestId.newId(),new UserId("a"),new UserId("b"),Money.of("1","USD"),"x",time);repo.saveNew(r);r.submit(time);assertThat(repo.findById(r.id()).orElseThrow().status()).isEqualTo(RequestStatus.DRAFT);}
@Test void optimisticVersionConflictIsDetected(){var time=Instant.parse("2026-01-01T00:00:00Z");var repo=new InMemoryExpenseRequestRepository();var r=ExpenseRequest.draft(ExpenseRequestId.newId(),new UserId("a"),new UserId("b"),Money.of("1","USD"),"x",time);repo.saveNew(r);var a=repo.findById(r.id()).orElseThrow();var b=repo.findById(r.id()).orElseThrow();a.submit(time);repo.save(a,0);b.submit(time);assertThatThrownBy(()->repo.save(b,0)).isInstanceOf(VersionConflictException.class);}
@Test void missingIdReturnsEmpty(){assertThat(new InMemoryExpenseRequestRepository().findById(ExpenseRequestId.newId())).isEmpty();}}
